1	/****************************************************************************
2	 * SiliconLoop - buggy producer/consumer demo
3	 *
4	 * Reproduces the failure class that a mock test cannot catch: a producer
5	 * that waits on a bounded FIFO with no exit condition. On real hardware
6	 * the FIFO fills up and the loop never terminates; in a mock the
7	 * "has space" predicate always returns true and the test passes.
8	 *
9	 * The FIFO here is simulated in RAM so that killing it does not take the
10	 * console down with it.
11	 *
12	 * Usage:
13	 *   buggy_app          run normally (consumer drains the FIFO)
14	 *   buggy_app stall    inject the fault (consumer stops draining)
15	 ****************************************************************************/
16	
17	#include <stdio.h>
18	#include <stdlib.h>
19	#include <string.h>
20	#include <unistd.h>
21	#include <pthread.h>
22	#include <sched.h>
23	
24	#define FIFO_SIZE      64
25	#define HEARTBEAT_PATH "/data/ai_agent/evidence/heartbeat.txt"
26	
27	static unsigned char g_fifo[FIFO_SIZE];
28	static int g_head;
29	static int g_tail;
30	static int g_count;
31	static int g_consumer_on = 1;
32	static unsigned long g_produced;
33	static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
34	
35	static int fifo_has_space(void)
36	{
37	    int has;
38	
39	    pthread_mutex_lock(&g_lock);
40	    has = (g_count < FIFO_SIZE);
41	    pthread_mutex_unlock(&g_lock);
42	    return has;
43	}
44	
45	static void fifo_put(unsigned char c)
46	{
47	    pthread_mutex_lock(&g_lock);
48	    g_fifo[g_head] = c;
49	    g_head = (g_head + 1) % FIFO_SIZE;
50	    g_count++;
51	    g_produced++;
52	    pthread_mutex_unlock(&g_lock);
53	}
54	
55	static void *consumer_thread(void *arg)
56	{
57	    (void)arg;
58	
59	    for (;;) {
60	        pthread_mutex_lock(&g_lock);
61	        if (g_consumer_on && g_count > 0) {
62	            g_tail = (g_tail + 1) % FIFO_SIZE;
63	            g_count--;
64	        }
65	        pthread_mutex_unlock(&g_lock);
66	        usleep(20000);
67	    }
68	
69	    return NULL;
70	}
71	
72	static void write_heartbeat(void)
73	{
74	    FILE *f = fopen(HEARTBEAT_PATH, "w");
75	
76	    if (f) {
77	        fprintf(f, "%lu\n", g_produced);
78	        fclose(f);
79	    }
80	}
81	
82	static void dump_pmp(void)
83	{
84	    unsigned long cfg[4];
85	    unsigned long addr[16];
86	    int i;
87	
88	    __asm__ __volatile__("csrr %0, 0x3a0" : "=r"(cfg[0]));
89	    __asm__ __volatile__("csrr %0, 0x3a1" : "=r"(cfg[1]));
90	    __asm__ __volatile__("csrr %0, 0x3a2" : "=r"(cfg[2]));
91	    __asm__ __volatile__("csrr %0, 0x3a3" : "=r"(cfg[3]));
92	
93	    __asm__ __volatile__("csrr %0, 0x3b0" : "=r"(addr[0]));
94	    __asm__ __volatile__("csrr %0, 0x3b1" : "=r"(addr[1]));
95	    __asm__ __volatile__("csrr %0, 0x3b2" : "=r"(addr[2]));
96	    __asm__ __volatile__("csrr %0, 0x3b3" : "=r"(addr[3]));
97	    __asm__ __volatile__("csrr %0, 0x3b4" : "=r"(addr[4]));
98	    __asm__ __volatile__("csrr %0, 0x3b5" : "=r"(addr[5]));
99	    __asm__ __volatile__("csrr %0, 0x3b6" : "=r"(addr[6]));
100	    __asm__ __volatile__("csrr %0, 0x3b7" : "=r"(addr[7]));
101	    __asm__ __volatile__("csrr %0, 0x3b8" : "=r"(addr[8]));
102	    __asm__ __volatile__("csrr %0, 0x3b9" : "=r"(addr[9]));
103	    __asm__ __volatile__("csrr %0, 0x3ba" : "=r"(addr[10]));
104	    __asm__ __volatile__("csrr %0, 0x3bb" : "=r"(addr[11]));
105	    __asm__ __volatile__("csrr %0, 0x3bc" : "=r"(addr[12]));
106	    __asm__ __volatile__("csrr %0, 0x3bd" : "=r"(addr[13]));
107	    __asm__ __volatile__("csrr %0, 0x3be" : "=r"(addr[14]));
108	    __asm__ __volatile__("csrr %0, 0x3bf" : "=r"(addr[15]));
109	
110	    for (i = 0; i < 16; i++) {
111	        unsigned c = (unsigned)((cfg[i / 4] >> ((i % 4) * 8)) & 0xff);
112	        printf("PMP%02d cfg=%02x R%d W%d X%d A%d L%d addr=%08lx top=%08lx\n",
113	               i, c,
114	               (c >> 0) & 1, (c >> 1) & 1, (c >> 2) & 1,
115	               (c >> 3) & 3, (c >> 7) & 1,
116	               addr[i], addr[i] << 2);
117	    }
118	}
119	
120	int main(int argc, char *argv[])
121	{
122	    pthread_t tid;
123	
124	    if (argc > 1 && strcmp(argv[1], "pmp") == 0) {
125	        dump_pmp();
126	        return 0;
127	    }
128	
129	    if (argc > 2 && strcmp(argv[1], "md") == 0) {
130	        unsigned long a = strtoul(argv[2], NULL, 0);
131	        const unsigned char *p = (const unsigned char *)a;
132	        int i;
133	
134	        printf("%08lx:", a);
135	        for (i = 0; i < 32; i++) {
136	            printf(" %02x", p[i]);
137	            if ((i % 16) == 15 && i != 31) {
138	                printf("\n%08lx:", a + i + 1);
139	            }
140	        }
141	        printf("\n");
142	        return 0;
143	    }
144	
145	    /* Run below the agent so a spinning producer cannot starve the
146	     * diagnostic path. The scheduler class stays SCHED_RR.
147	     */
148	    {
149	        struct sched_param sp;
150	
151	        if (sched_getparam(0, &sp) == 0) {
152	            sp.sched_priority = 50;
153	            sched_setparam(0, &sp);
154	        }
155	    }
156	
157	    if (argc > 1 && strcmp(argv[1], "stall") == 0) {
158	        g_consumer_on = 0;
159	        printf("buggy_app: consumer disabled, FIFO will fill up\n");
160	    }
161	
162	    pthread_create(&tid, NULL, consumer_thread, NULL);
163	
164	    printf("buggy_app: producing, heartbeat at %s\n", HEARTBEAT_PATH);
165	
166	    /* Wait for the agent to create the evidence directory, then publish
167	     * one heartbeat before the FIFO can fill. Without this the stalled
168	     * run leaves no heartbeat at all, and "file missing" is weaker
169	     * evidence than "value never changed".
170	     */
171	    {
172	        int tries;
173	
174	        for (tries = 0; tries < 300; tries++) {
175	            FILE *probe = fopen(HEARTBEAT_PATH, "w");
176	
177	            if (probe) {
178	                fprintf(probe, "0\n");
179	                fclose(probe);
180	                break;
181	            }
182	
183	            sleep(1);
184	        }
185	    }
186	
187	    for (;;) {
188	        /* The bug: no exit condition, no timeout, no error path.
189	         * The usleep() is a concession to demonstrability, not part of
190	         * the fault. A bare spin here starves every lower-priority
191	         * thread on this single-core board, including the agent's own
192	         * CLI, so the diagnostic system never gets to run. That was
193	         * reproduced first; the sleep was added afterwards so the
194	         * fault stays observable. The loop still never terminates and
195	         * the task still never makes progress.
196	         */
197	        while (!fifo_has_space())
198	            usleep(1000);
199	
200	        fifo_put((unsigned char)(g_produced & 0xff));
201	
202	        if ((g_produced % 50) == 0) {
203	            write_heartbeat();
204	        }
205	
206	        usleep(10000);
207	    }
208	
209	    return 0;
210	}
